/* ============ أدوات مساعدة ============ */

export const fmt = (n) => new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(Math.round(n));
export const fmt2 = (n) => new Intl.NumberFormat("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
export const emptyLine = () => ({ account: ACCOUNTS[0].name, costCenter: "", department: DEPARTMENTS[0], debit: "", credit: "", employeeId: null });
export const costCenterName = (id) => COST_CENTERS.find((c) => c.id === id)?.name || "—";

/* مدة الخدمة بالسنوات/الشهور/الأيام بين تاريخين */
export function serviceDuration(startStr, endStr) {
  const start = new Date(startStr);
  const end = new Date(endStr);
  let years = end.getFullYear() - start.getFullYear();
  let months = end.getMonth() - start.getMonth();
  let days = end.getDate() - start.getDate();
  if (days < 0) {
    months -= 1;
    const prevMonth = new Date(end.getFullYear(), end.getMonth(), 0);
    days += prevMonth.getDate();
  }
  if (months < 0) { years -= 1; months += 12; }
  const totalYears = years + months / 12 + days / 365;
  return { years, months, days, totalYears: Math.max(totalYears, 0) };
}

/* مكافأة نهاية الخدمة وفق نظام العمل السعودي (المادتان 84 و85) - حساب تقديري توضيحي */
export function calcEOS(employee, endDate, reason) {
  const wage = employee.basicSalary + employee.housingAllowance;
  const { totalYears } = serviceDuration(employee.hireDate, endDate);
  const first5 = Math.min(totalYears, 5);
  const remaining = Math.max(totalYears - 5, 0);
  const fullReward = first5 * 0.5 * wage + remaining * 1 * wage;

  let ratio = 1;
  let ratioNote = "استحقاق كامل";
  if (reason === "resign") {
    if (totalYears < 2) { ratio = 0; ratioNote = "أقل من سنتين خدمة — لا يستحق مكافأة"; }
    else if (totalYears < 5) { ratio = 1 / 3; ratioNote = "استقالة بين 2 و5 سنوات — يستحق ثلث المكافأة"; }
    else if (totalYears < 10) { ratio = 2 / 3; ratioNote = "استقالة بين 5 و10 سنوات — يستحق ثلثي المكافأة"; }
    else { ratio = 1; ratioNote = "استقالة بعد 10 سنوات فأكثر — استحقاق كامل"; }
  }

  return { wage, totalYears, fullReward, ratio, ratioNote, finalAmount: fullReward * ratio };
}

export function payrollRow(emp) {
  const gross = emp.basicSalary + emp.housingAllowance + emp.transportAllowance + (emp.otherAllowance || 0);
  const gosi = emp.gosiAmount != null && emp.gosiAmount > 0
    ? emp.gosiAmount
    : (emp.gosiApplicable ? Math.round((emp.basicSalary + emp.housingAllowance) * 0.0975) : 0);
  const advances = emp.advances || 0;
  const absence = emp.absenceDeduction || 0;
  const otherDed = emp.otherDeductions || 0;
  const totalDed = gosi + advances + absence + otherDed;
  const net = gross - totalDed;
  return { gross, gosi, advances, absence, otherDed, totalDed, net };
}

/* أدوات مساعدة لتسوية مستحقات الإجازة ومباشرة العودة */
export const dailyRate = (emp) => (emp.basicSalary + emp.housingAllowance + emp.transportAllowance + (emp.otherAllowance || 0)) / 30;
export const daysInMonth = (monthStr) => { const [y, m] = monthStr.split("-").map(Number); return new Date(y, m, 0).getDate(); };
export const MONTH_NAMES = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
export const monthLabel = (monthStr) => { const [y, m] = monthStr.split("-").map(Number); return `${MONTH_NAMES[m - 1]} ${y}`; };

/* رصيد أيام الإجازة المتراكم منذ آخر عودة من إجازة (أو تاريخ المباشرة إن كانت أول إجازة) */
export function accruedLeaveDays(emp, uptoDateStr) {
  const refDate = emp.lastLeaveReturnDate || emp.hireDate;
  const { totalYears } = serviceDuration(emp.hireDate, uptoDateStr);
  const annualEntitlement = totalYears >= 5 ? 30 : 21;
  const daysSinceRef = Math.max((new Date(uptoDateStr) - new Date(refDate)) / 86400000, 0);
  return { refDate, annualEntitlement, days: (daysSinceRef / 365) * annualEntitlement };
}

/* رصيد حساب الموظف (ذمم الموظفين) من واقع القيود المرحّلة فعلاً */
export function employeeAccountBalance(entries, employeeId) {
  let debit = 0, credit = 0;
  entries.forEach((e) => e.lines.forEach((l) => {
    if (l.account === "ذمم الموظفين - مستحقات وإجازات" && l.employeeId === employeeId) {
      debit += Number(l.debit || 0);
      credit += Number(l.credit || 0);
    }
  }));
  return credit - debit;
}

/* رصيد ذمم عميل معيّن (مدين له = موجب) من واقع القيود المرحّلة فعلياً */
/* دالة عامة: رصيد أي طرف (عميل أو مورد) على حساب معيّن، موسوماً بحقل مرجعي (customerId/supplierId) */
export function partyAccountBalance(entries, account, tagField, tagValue) {
  let debit = 0, credit = 0;
  entries.forEach((e) => e.lines.forEach((l) => {
    if (l.account === account && l[tagField] === tagValue) {
      debit += Number(l.debit || 0);
      credit += Number(l.credit || 0);
    }
  }));
  return { debit, credit };
}

export function customerAccountBalance(entries, customerId) {
  const { debit, credit } = partyAccountBalance(entries, "ذمم مدينة", "customerId", customerId);
  return debit - credit;
}

export function supplierAccountBalance(entries, supplierId) {
  const { debit, credit } = partyAccountBalance(entries, "ذمم دائنة - موردين", "supplierId", supplierId);
  return credit - debit;
}

/* إجمالي المبلغ المسدد من فاتورة معيّنة عبر كل سندات القبض المرتبطة بها */
export function invoicePaidAmount(receipts, invoiceId) {
  return receipts.reduce((sum, r) => {
    const alloc = (r.allocations || []).find((a) => a.invoiceId === invoiceId);
    return sum + (alloc ? alloc.amount : 0);
  }, 0);
}

/* تحديد نوع الفاتورة وفق متطلبات هيئة الزكاة والضريبة والجمارك (فاتورة ضريبية قياسية للمنشآت، مبسّطة للأفراد) */
export function invoiceTypeForCustomer(customer) {
  return customer && customer.customerType === "business" && customer.vatNumber ? "standard" : "simplified";
}

/* توليد حمولة رمز الاستجابة السريعة (QR) وفق معيار TLV المعتمد من هيئة الزكاة والضريبة والجمارك (المرحلة الأولى) */
export function buildZatcaQrPayload(sellerName, sellerVat, isoTimestamp, invoiceTotal, vatTotal) {
  const encoder = new TextEncoder();
  const tlv = (tag, value) => {
    const bytes = encoder.encode(String(value || ""));
    return new Uint8Array([tag, bytes.length, ...bytes]);
  };
  const parts = [
    tlv(1, sellerName),
    tlv(2, sellerVat),
    tlv(3, isoTimestamp),
    tlv(4, invoiceTotal.toFixed(2)),
    tlv(5, vatTotal.toFixed(2)),
  ];
  const total = parts.reduce((s, p) => s + p.length, 0);
  const buf = new Uint8Array(total);
  let offset = 0;
  parts.forEach((p) => { buf.set(p, offset); offset += p.length; });
  let binary = "";
  buf.forEach((b) => { binary += String.fromCharCode(b); });
  return btoa(binary);
}

export function nextDocNumber(list, prefix, field) {
  const n = list.length ? Math.max(...list.map((x) => Number((x[field] || "").split("-").pop()) || 0)) + 1 : 1;
  return `${prefix}-${String(n).padStart(5, "0")}`;
}

export function entryTotal(entry) {
  return entry.lines.reduce((s, l) => s + Number(l.debit || 0), 0);
}

export function filterEntries(entries, companyId) {
  return companyId === "all" ? entries : entries.filter((e) => e.company === companyId);
}

/* تجميع الأرصدة لكل حساب من كل الأسطر ضمن قيود شركة معيّنة */
export function aggregateAccounts(entries, companyId) {
  const list = filterEntries(entries, companyId);
  const map = {};
  ACCOUNTS.forEach((a) => (map[a.name] = { debit: 0, credit: 0 }));
  list.forEach((e) => {
    e.lines.forEach((l) => {
      if (!map[l.account]) map[l.account] = { debit: 0, credit: 0 };
      map[l.account].debit += Number(l.debit || 0);
      map[l.account].credit += Number(l.credit || 0);
    });
  });
  return map;
}
